result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "digit_dp.py", "content": """"Digit DP: count integers in [a, b] whose decimal digit sum is divisible by k."""

from functools import lru_cache


def count(a: int, b: int, k: int) -> int:
    """Return the number of n with a <= n <= b and (sum of digits of n) % k == 0."""
    if a > b:
        raise ValueError("require a <= b")
    if k < 1:
        raise ValueError("require k >= 1")

    digits = str(b)

    def count_upto(n_str: str) -> int:
        """Count n in [0, int(n_str)] with digit sum % k == 0 (memoized digit DP)."""

        @lru_cache(maxsize=None)
        def dp(pos: int, rem: int, tight: bool) -> int:
            if pos == len(n_str):
                return 1 if rem == 0 else 0
            limit = int(n_str[pos]) if tight else 9
            total = 0
            for d in range(limit + 1):
                total += dp(pos + 1, (rem + d) % k, tight and d == limit)
            return total

        return dp(0, 0, True)

    return count_upto(digits) - count_upto(str(a - 1)) if a > 0 else count_upto(digits)
